def rollback_static(intents):
 conflicts=[]
 for value in reversed(intents):
  path=Path(value['path'])
  if not path.exists() and not path.is_symlink():
   if value['before_sha256'] is not None:conflicts.append(str(path))
   continue
  if path.is_symlink() or not path.is_file():conflicts.append(str(path));continue
  current=filehash(path)
  if current==value['before_sha256']:continue
  if current!=value['after_sha256']:conflicts.append(str(path));continue
  if value['before_sha256'] is None:path.unlink()
  else:data=Path(value['before_source']).read_bytes();need(sha(data)==value['before_sha256'],'STATIC_ROLLBACK_COPY_PIN');atomic_public(path,data,value['metadata'])
 return conflicts

